def solution(input_str):
    """
    Solve the ranger deliver problem.

    Args:
        input_str: Input string containing all parameters

    Returns:
        String with the minimum delivery time
    """
    lines = input_str.strip().split('\n')
    line1 = lines[0].split()
    line2 = lines[1].split()

    xp, yp, vp = map(float, line1)
    x, y, v, r = map(float, line2)

    # Persephone's initial position
    P0 = (xp, yp)
    # Qwerty's initial position
    S = (x, y)

    # Calculate orbital radius and angle
    R = math.sqrt(xp**2 + yp**2)

    # Handle edge case: already at the same position
    if R < 1e-9:
        time = distance(S, P0) / v
        return f"{time:.10f}"

    initial_angle = math.atan2(yp, xp)
    angular_speed = vp / R

    def dist(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    def get_pos(theta):
        return (R * math.cos(theta), R * math.sin(theta))

    def check(t):
        """Can Qwerty reach Persephone at time t?"""
        theta = initial_angle + angular_speed * t
        if theta < 0:
            theta += 2 * math.pi
        P = get_pos(theta)
        d = dist(S, P)
        return d <= v * t

    def check_with_safe(t):
