        time_offset = (vp * t) / v
        return time_offset <= t

    def is_safe_path(start, end):
        """Check if segment from start to end stays >= r from origin"""
        if BisectionCheck.is_segment_safe(start, end, r):
            return True
        return False
    # Import after defining variables

    # First check if already safe position or already met
    if R < 1e-12:
        return format(dist(S, (0, 0)) / v, '.10f')

    # Create binary search for minimum time
    left, right = 0.0, 1e9
    tolerance = 1e-7

