        mid = left + (right - left) / 2
        theta = initial_angle + angular_speed * mid
        P = (R * math.cos(theta), R * math.sin(theta))
        d = math.hypot(P[0] - S[0], P[1] - S[1])

        if d <= v * mid:
            right = mid
        else:
            left = mid

    # Check if this global minimum respects safety
    mid = (left + right) / 2
