def is_safe(start, end):
    # Check if the line segment from start to end is safe
    return SegmentSafeCheck.is_safe(start, end)

class SegmentSafeCheck:
    """Check if segment stays outside circle of radius r"""

    @staticmethod
    def is_safe(start, end, r=1e-6):
        """
        Check if line segment stays at distance >= r from origin.
        Uses geometric approach to find closest point.
        """
        dx = end[0] - start[0]
        dy = end[1] - start[1]

        if dx**2 + dy**2 < 1e-12:
            d = math.hypot(start[0], start[1])
            return d >= r - 1e-9

        t = max(0, min(1, -start[0]*dx - start[1]*dy / (dx**2 + dy**2)))

        closest = (start[0] + t * dx, start[1] + t * dy)
        d = math.hypot(closest[0], closest[1])

        return d >= r - 1e-9

class BisectionCheck:
    """Binary search helper"""
    @staticmethod
    def is_segment_safe(start, end, r):
        return SegmentSafeCheck.is_safe(start, end, r)

