    matrix = []
    for i in range(1, n + 1):
        row = list(map(int, lines[i].strip().split()))
        matrix.append(row)

    # Precompute factorials for permutations
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Precompute permutations P(n, k) = n! / (n-k)!
    perm = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for k in range(i + 1):
            perm[i][k] = fact[i] * pow(fact[i - k], MOD - 2, MOD) % MOD

    result = 0

    for i in range(n):
        col_used = [set() for _ in range(n)]
        for r in range(i):
            for c in range(n):
                col_used[c].add(matrix[r][c])

        for j in range(n):
            used_in_row = set()
            for k in range(j):
                used_in_row.add(matrix[i][k])
                col_used[k] = col_used[k]  # Already fixed

            available = set()
            for v in range(1, n + 1):
