            new_nums = [new_nums[k] for k in range(len(new_nums)) if k != i] + [result]
            new_nums = [a[idx] for idx in range(n) if idx != i and idx != j] + [result]
            new_state = get_state(new_nums)

            if new_state not in visited:
                visited.add(new_state)
                queue.append((new_state, [(x, y)]))

