def parse_input(inp):
    line = inp.strip()
    parts = line.split()
    n, r = int(parts[0]), int(parts[1])
    return n, r

def get_integers_in_circle(r):
    """Get all integer points (x, y) such that x^2 + y^2 <= r^2"""
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))
    return points

def squared_distance(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def calculate_total_sq_dist(points):
    total = 0
    m = len(points)
    for i in range(m):
        for j in range(i + 1, m):
            total += squared_distance(points[i], points[j])
    return total

def brute_force_then_optimize(n, r):
    points = get_integers_in_circle(r)

    best_score = -1
    best_places = None

    # For small n and r, we can try different strategies
    # Strategy 1: Check if placing all points at same location is optimal
    for p in points:
        score = calculate_total_sq_dist([p] * n)
        if score > best_score:
            best_score = score
            best_places = [p] * n

    # Strategy 2: For n=2, put at opposite ends
    if n == 2:
        best_score = -1
        best_places = None
        for p in points:
            for q in points:
                score = calculate_total_sq_dist([p, q])
                if score > best_score:
                    best_score = score
                    best_places = [p, q]

    # Strategy 3: Try to place points symmetrically
    if n >= 3 and best_score < 0:
        # Try various configurations
        configs = generate_configs(n, points, r, max_attempts=20)
        for config in configs:
            score = calculate_total_sq_dist(config)
            if score > best_score:
                best_score = score
                best_places = config

    # If still no improvement, fallback to best found
    if best_score < 0:
        best_score = 0
        best_places = []

    # Format output
    lines = [str(best_score)]
    for (x, y) in best_places:
        lines.append(f"{x} {y}")
    return '\n'.join(lines)

def generate_configs(n, points, r, max_attempts):
    configs = []
    import random
    random.seed(42)  # For reproducibility

    seen = set()

    while len(configs) < max_attempts:
        config = []
        # Try to place points in distinct positions first, then allow repetitions
        selected = []
        for _ in range(n):
            idx = random.randint(0, len(points) - 1)
            p = points[idx]
            selected.append(p)
        config = tuple(sorted(selected))  # Normalize
        if config not in seen:
            seen.add(config)
            configs.append(list(config))

    return configs

