    n, k, l = map(int, lines[:3])

    MOD = 998244353

    # Precompute factorials and inverse factorials
    max_val = 2 * n + 5
    fact = [1] * max_val
    inv_fact = [1] * max_val

    for i in range(1, max_val):
        fact[i] = (fact[i - 1] * i) % MOD

    inv_fact[max_val - 1] = pow(fact[max_val - 1], MOD - 2, MOD)
    for i in range(max_val - 2, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    def beta(a, b):
        # Beta function: B(a, b) = (a-1)! * (b-1)! / (a+b-2)!
        if a <= 0 or b <= 0:
            return 0
        return fact[a - 1] * fact[b - 1] % MOD * inv_fact[a + b - 2] % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    ans = 0

    for j in range(k, n + 1):
        for m in range(n - j + 1):
            # Term: C(n,j) * C(n-j,m) * (-1)^m * 2^(j+m) * B(j+m+1, j+m+1)
            term = nCr(n, j) % MOD
            term = term * nCr(n - j, m) % MOD

            # Alternating sign
            if m % 2 == 1:
                term = (MOD - term) % MOD

            # Multiply by 2^(j+m)
            term = term * pow(2, j + m, MOD) % MOD

            # Multiply by Beta(j+m+1, j+m+1)
            term = term * beta(j + m + 1, j + m + 1) % MOD

            ans = (ans + term) % MOD

    # Multiply by l (modular multiplication)
    l_mod = l % MOD
    ans = ans * pow(l_mod, MOD - 2, MOD) % MOD

    return str(ans)

