    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    def bfs(start):
        for i in range(1, n + 1):
            dist[start][i] = float('inf')
        dist[start][start] = 0
        queue = [start]

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    for start in range(1, n + 1):
        bfs(start)

    # Find the 4 cities that maximize the total distance
    # We need to find cities a, b, c, d (all distinct) maximizing:
    # dist[a][b] + dist[b][c] + dist[c][d]

    max_total = -1
    result = None

    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if dist[a][b] == float('inf'):
                continue
            for c in range(1, n + 1):
