from itertools import combinations_with_replacement, permutations

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())
    MOD = 1000000007

    def is_good(arr):
        """Check if array forms a good cycle (all adjacent differences = 1)"""
        r = len(arr)
        if r < 2:
            return False
        for i in range(r):
            if abs(arr[i] - arr[(i + 1) % r]) != 1:
                return False
        return True

    def count_distinct_good_arrays(elements):
        """Count distinct good arrays that can be formed from this multiset"""
        # Use a set to track unique good arrays (as non-decreasing representations)
        good_found = set()

        for p in set(permutations(elements)):
            if is_good(p):
                # Create canonical form (as tuple)
                good_found.add(p)

        return len(good_found)

    ans = 0

    for length in range(1, n + 1):
        for combo in combinations_with_replacement(range(1, m + 1), length):
            count = count_distinct_good_arrays(list(combo))
            # Count if we can form at least 1 and at most k distinct good arrays
            if 1 <= count <= k:
                ans = (ans + 1) % MOD

    return str(ans)

