import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0\n'

    # dist dict: maps position to minimum moves to reach it
    dist = {a: 0}

    # Min-heap: (moves, position)
    heap = [(0, a)]

    while heap:
        moves, pos = heapq.heappop(heap)

        # If we found a better path to this position already, skip
        if moves > dist.get(pos, float('inf')):
            continue

        # If we reached b, return the answer
        if pos == b:
            return str(moves) + '\n'

        # Generate all possible next positions
        next_positions = set()

        # Option 1: Subtract 1
        if pos - 1 >= b:
            next_positions.add(pos - 1)

        # Option 2: Subtract pos % xi for each xi
        for xi in x:
            remainder = pos % xi
            if remainder > 0:
                next_pos = pos - remainder
                if next_pos >= b:
                    next_positions.add(next_pos)

        # Add unvisited or improvable positions to heap
        for next_pos in next_positions:
            new_moves = moves + 1
            if next_pos not in dist or new_moves < dist[next_pos]:
                dist[next_pos] = new_moves
                heapq.heappush(heap, (new_moves, next_pos))

    # Fallback: worst case is subtracting 1 repeatedly
    return str(a - b) + '\n'

