                    right_ok = all(matrix[i+r][j+size-1] == '1' for r in range(size))

                    if not (top_ok and bottom_ok and left_ok and right_ok):
                        continue

                    # Check interior is all 0s (except must have at least one 1 - but wait, 
                    # the frame itself already has 1s, so the "contain at least one 1" is satisfied)
                    # Actually re-reading: "must contain at least one 1" - the frame has 1s, so OK
                    # But also: frame interior doesn't matter for validity, only border touching matters

                    # Check no external 1s touching (by side or corner)
