                    if not interior_ok:
                        continue

                    # Check no external 1s touching (cells at exactly distance r from each border cell)
                    touching_ok = True
                    for dr in range(-r-1, r+2):
                        for dc in range(-r-1, r+2):
                            if abs(dr) + abs(dc) > 0 and abs(dr) + abs(dc) <= r:
