def solution(input_str):
    n, k = map(int, input_str.split())
    MOD = 998244353

    # If k > n, impossible to have strictly increasing chain of length k
    if k > n:
        return "0"

    # If k = 1, any single element is stable, so n choices
    if k == 1:
        return str(n % MOD)

    # The maximum chain length is bounded by powers of 2: 1, 2, 4, 8, ...
    # Since 2^18 > 500000, any chain longer than ~18 elements requires n > 500000
    # For safe bound, if k >= 32, answer is 0 for n <= 500000
    if k >= 32:
        return "0"

    # dp[j] = number of chains of current length ending at value j
    # For length 1, every position has exactly one chain: [j]
    dp = [1] * (n + 1)

    # Build chains for lengths 2 to k
    for length in range(2, k + 1):
        new_dp = [0] * (n + 1)

        # For each divisor d, add its chain count to all multiples of d
        for d in range(1, n + 1):
            if dp[d] == 0:
                continue
            # j = 2*d, 3*d, 4*d, ... (multiples greater than d)
            for j in range(2 * d, n + 1, d):
                new_dp[j] = (new_dp[j] + dp[d]) % MOD

        dp = new_dp

    # Sum all chains of length k ending at any position
    ans = sum(dp[1:]) % MOD
    return str(ans)

