from functools import lru_cache

MOD = 1051131

@lru_cache(maxsize=None)
def count_common_divisors(a, b):
    g = math.gcd(a, b)
    # Count divisors of gcd(a,b)
    count = 0
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            if i * i == g:
                count += 1
            else:
                count += 2
    return count

def mat_mul(A, B, n):
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p, n):
    if p == 0:
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = [row[:] for row in A]
    while p > 0:
        if p & 1:
            result = mat_mul(result, base, n)
        base = mat_mul(base, base, n)
        p >>= 1
    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    m, t_str, s = lines[0].split()
    m = int(m)
    t = int(t_str)
    s = int(s)

    a_vals = list(map(int, lines[1].split()))
    n = 2 * m

    # Generate array a
    a = [0] * n
    for i in range(s):
        a[i] = a_vals[i]
    for i in range(s, n):
        a[i] = (101 * a[s-1] - s + 10007) % MOD

    # Build transition matrix M[i][j] = ways from i to j (0-indexed)
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                M[i][j] = 1  # Stay in place
            else:
                g = count_common_divisors(i + 1, j + 1)
                M[i][j] = pow(2, g, MOD)  # Move with bridge count

    # Compute M^t
    Mt = mat_pow(M, t, n)

    # Get initial state vector (ways to reach each island from home)
    # With a_k bridges from home to island k
    initial = [x % MOD for x in a]

    # Compute final state: Mt * initial
    final_state = [0] * n
    for i in range(n):
        for j in range(n):
            final_state[i] = (final_state[i] + Mt[i][j] * initial[j]) % MOD

    # XOR sum of all answers
    ans_xor = 0
    for val in final_state:
        ans_xor ^= val

    return f"{ans_xor}\n"

