def solution(input_str):
    """
    Solve the game theory problem where players take turns increasing either boxes (a) or items (b).
    The player who causes a^b >= n loses.
    """
    a, b, n = map(int, input_str.split())

    memo = {}

    def is_winning(a, b):
        """
        Returns True if the current player can force a win from state (a, b).
        A player wins if they can make a move that leads to a state where
        the opponent loses (i.e., the opponent cannot force a win).
        """
        if (a, b) in memo:
            return memo[(a, b)]

        # Game ends when a^b >= n - the player who made this move loses
        if a ** b >= n:
            return False

        # Check if there's at least one move that forces the opponent into a losing position
        can_force_lose_opponent = False

        # Option 1: Increase the number of boxes by 1
        if (a + 1) ** b < n:
            if not is_winning(a + 1, b):
                can_force_lose_opponent = True

        # Option 2: Increase the number of items by 1
        if not can_force_lose_opponent and a ** (b + 1) < n:
            if not is_winning(a, b + 1):
                can_force_lose_opponent = True

        memo[(a, b)] = can_force_lose_opponent
        return can_force_lose_opponent

    if is_winning(a, b):
        return "Stas\n\n"
    else:
        return "Masha\n\n"

def solution(input_str):
    import sys
    input_str = input_str.strip()
    lines = input_str.split('\n')

    # Parse t
    t = int(lines[0])

    # Generate Fibonacci numbers
    fib = [1, 2]
    while fib[-1] < 10**18:
        fib.append(fib[-1] + fib[-2])

    # Memoization
    memo = {}

    def count(n, idx):
        if n == 0:
            return 1  # Found a valid decomposition (we'll handle non-empty later)
        if n < 0:
            return 0
        if idx < 0:
            return 0
        if (n, idx) in memo:
            return memo[(n, idx)]

        # Option 1: Don't use F[idx]
        res = count(n, idx - 1)

        # Option 2: Use F[idx] (if F[idx] <= n)
        if fib[idx] <= n:
            res += count(n - fib[idx], idx - 1)

        memo[(n, idx)] = res
        return res

    results = []
    for i in range(1, t + 1):
        n = int(lines[i])
        # count includes the empty sum, but problem says non-empty set
        # So subtract 1 if the result includes the empty sum
        ans = count(n, len(fib) - 1)
        if ans > 0:
            results.append(str(ans - 1))
        else:
            results.append(str(ans))

    return '\n'.join(results)
